def write_batch(batch):
    total = 0
    for r in batch:
        assert set(r.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}, r["case_id"]
        assert 0 <= r["confidence"] <= 1
        assert all(isinstance(v, bool) for k, v in r["trigger"].items() if k != "reason")
        p = os.path.join(BASE, r["case_id"] + ".json")
        with open(p, "w", encoding="utf-8") as f:
            json.dump(r, f, ensure_ascii=False, indent=2)
        with open(p, encoding="utf-8") as f:
            back = json.load(f)
        assert back["case_id"] == r["case_id"] and len(back) == 5
        total += os.path.getsize(p)
        print("OK", r["case_id"], os.path.getsize(p))
    return total

if __name__ == "__main__":
    t = write_batch(BATCH1)
    print("BATCH1_DONE", len(BATCH1), t)
